def is_subset_sum(set, n, sum):
    """Write a function to determine if there is a subset of the given set with sum equal to the given sum."""
    if sum == 0:
        return True
    if n <= 0:
        return False
    reachable = {0}
    count = 0
    for num in set:
        if count >= n:
            break
        count += 1
        snapshot = reachable.copy()
        for s in snapshot:
            reachable.add(s + num)
        if sum in reachable:
            return True
    return sum in reachable
